const plants=plantRows.map(([icon,name,variety,species,density,category])=>({icon,name,variety,species,density,category}));
const categories=['All','Alliums','Brassicas','Nightshades','Cucurbits','Legumes','Roots','Greens','Other','Perennials','Fruit','Herbs'];
const demo={year:2026,years:[2026],beds:[{id:'kitchen',year:2026,name:'Kitchen Garden',shape:'rectangle',length:8,width:4,plants:{0:plants.find(p=>p.name==='Tomato'),1:plants.find(p=>p.name==='Basil'),2:plants.find(p=>p.name==='Cabbage'),4:plants.find(p=>p.name==='Green Bean'),5:plants.find(p=>p.name==='Spinach'),6:plants.find(p=>p.name==='Carrot')}}],ideas:['Three Sisters Bed','Tea & Medicinal Herbs','Moon Garden']};
let state=load(),active=null,selected=plants.find(p=>p.name==='Tomato'),cellIndex=null,shape='rectangle',plantCategory='All',plantSearch='';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function clone(x){return JSON.parse(JSON.stringify(x))}function load(){try{return JSON.parse(localStorage.getItem(KEY))||clone(demo)}catch{return clone(demo)}}function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function cap(s){return s[0].toUpperCase()+s.slice(1)}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),1600)}
function years(){$('#year').innerHTML=state.years.sort().map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}function beds(){const list=state.beds.filter(b=>b.year===state.year);$('#bedList').innerHTML=list.length?list.map(b=>`<button class="bed-card" data-id="${b.id}"><span class="thumb ${b.shape}"></span><span><h3>${esc(b.name)}</h3><p>${cap(b.shape)} · ${b.length} × ${b.width}</p><small>${Object.keys(b.plants||{}).length} planted squares</small><em>Open visual planner →</em></span><span class="delete" data-delete="${b.id}">×</span></button>`).join(''):`<div class="empty-card"><b>No beds committed for ${state.year}</b><br>Create one—or enjoy having promised yourself nothing.</div>`}function ideas(){$('#ideaList').innerHTML=state.ideas.length?state.ideas.map((n,i)=>`<article class="idea"><span>🌱</span><div><h3>${esc(n)}</h3><p>Loose concept · not committed</p></div><button data-commit="${i}">Add to ${state.year} Plan</button></article>`).join(''):'<div class="empty-card">No idea beds yet.</div>'}
function palette(){const q=plantSearch.trim().toLowerCase();const visible=plants.filter(p=>(plantCategory==='All'||p.category===plantCategory)&&(!q||[p.name,p.variety,p.species,p.category].some(v=>String(v).toLowerCase().includes(q))));$('#plantFilters').innerHTML=categories.map(c=>`<button type="button" class="filter-chip ${c===plantCategory?'active':''}" data-category="${c}">${c}</button>`).join('');$('#palette').innerHTML=visible.length?visible.map(p=>{const i=plants.indexOf(p);return `<button class="palette ${p===selected?'selected':''}" data-plant="${i}" title="${esc(p.variety)}"><span>${p.icon}</span><small>${esc(p.name)}</small></button>`}).join(''):'<p class="no-plants">No crops match that filter.</p>';$('#paletteCount').textContent=`${visible.length} of ${plants.length} crops`}
function show(name){$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name).classList.add('active')}function openBed(id){active=state.beds.find(b=>b.id===id);show('planner');planner()}
function planner(){const canvas=$('#canvas'),grid=$('#grid');if(!active){canvas.style.display='none';$('#empty').style.display='block';palette();return}$('#empty').style.display='none';canvas.style.display='block';canvas.className='canvas '+active.shape;$('#plannerTitle').textContent=active.name;$('#plannerMeta').textContent=`${active.year} · ${cap(active.shape)} · ${active.length} × ${active.width} squares`;const cols=Math.max(2,Math.min(12,active.length)),rows=Math.max(2,Math.min(12,active.width));grid.style.gridTemplateColumns=`repeat(${cols},1fr)`;grid.innerHTML='';for(let i=0;i<cols*rows;i++){const c=document.createElement('button');c.className='cell';const x=i%cols,y=Math.floor(i/cols),nx=(x+.5-cols/2)/(cols/2),ny=(y+.5-rows/2)/(rows/2);if(['circle','keyhole'].includes(active.shape)&&nx*nx+ny*ny>1){c.classList.add('disabled');c.disabled=true}if(active.shape==='keyhole'&&(nx*nx+ny*ny<.065||(Math.abs(nx)<.13&&ny>.08))){c.classList.add('disabled');c.disabled=true}const p=active.plants?.[i];if(p)c.innerHTML=`<span class="density">${Array.from({length:Math.min(p.density||1,16)},()=>`<i>${p.icon}</i>`).join('')}</span><small>${esc(p.name)}</small>`;c.onclick=()=>plantForm(i);grid.appendChild(c)}palette()}
function plantForm(i){cellIndex=i;const p=active.plants?.[i]||selected;$('#plantTitle').textContent=active.plants?.[i]?'Edit Plant':'Plant a Square';$('#plantIcon').textContent=p.icon||'🌱';$('#plantName').value=p.name||'';$('#variety').value=p.variety||'';$('#species').value=p.species||'';$('#density').value=[1,4,9,16].includes(+p.density)?+p.density:1;$('#notes').value=p.notes||'';$('#remove').style.visibility=active.plants?.[i]?'visible':'hidden';$('#plantDialog').showModal()}
$$('nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));$('#year').onchange=e=>{state.year=+e.target.value;persist();beds();ideas()};$('#addYear').onclick=()=>{const y=+prompt('Growing season year',Math.max(...state.years)+1);if(y>2000&&!state.years.includes(y)){state.years.push(y);state.year=y;persist();render()}};$('#newBed').onclick=()=>$('#bedDialog').showModal();$('.shapes').onclick=e=>{const b=e.target.closest('[data-shape]');if(!b)return;shape=b.dataset.shape;$$('.shapes button').forEach(x=>x.classList.toggle('selected',x===b));$('.keynote').style.display=shape==='keyhole'?'block':'none';if(['square','circle','keyhole'].includes(shape))$('#width').value=$('#length').value};$('#length').oninput=()=>{if(['square','circle','keyhole'].includes(shape))$('#width').value=$('#length').value};$('#create').onclick=e=>{e.preventDefault();const name=$('#bedName').value.trim();if(!name)return $('#bedName').reportValidity();const length=+$('#length').value,width=['square','circle','keyhole'].includes(shape)?length:+$('#width').value;active={id:'bed-'+Date.now(),year:state.year,name,shape,length,width,plants:{}};state.beds.push(active);persist();$('#bedDialog').close();beds();show('planner');planner();toast('Garden bed created')};$('#bedList').onclick=e=>{const d=e.target.closest('[data-delete]');if(d){e.stopPropagation();if(confirm('Delete this bed and its planted layout?')){state.beds=state.beds.filter(b=>b.id!==d.dataset.delete);if(active?.id===d.dataset.delete)active=null;persist();beds()}return}const b=e.target.closest('[data-id]');if(b)openBed(b.dataset.id)};$('#palette').onclick=e=>{const b=e.target.closest('[data-plant]');if(b){selected=plants[+b.dataset.plant];palette()}};$('#plantFilters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;plantCategory=b.dataset.category;palette()};$('#plantSearch').oninput=e=>{plantSearch=e.target.value;palette()};$('#custom').onclick=()=>{selected={icon:'🌱',name:'',variety:'',species:'',density:1,category:'Custom'};if(active){cellIndex=null;$('#plantTitle').textContent='Custom Plant';$('#plantIcon').textContent='🌱';$('#plantName').value='';$('#variety').value='';$('#species').value='';$('#density').value=1;$('#notes').value='';$('#remove').style.visibility='hidden';$('#plantDialog').showModal()}else toast('Open a garden bed first')};$('#savePlant').onclick=e=>{e.preventDefault();const name=$('#plantName').value.trim();if(!name)return $('#plantName').reportValidity();if(cellIndex===null)return;active.plants??={};active.plants[cellIndex]={icon:$('#plantIcon').textContent,name,variety:$('#variety').value,species:$('#species').value,density:+$('#density').value,notes:$('#notes').value};persist();$('#plantDialog').close();planner();beds();toast('Plant saved')};$('#remove').onclick=()=>{delete active.plants[cellIndex];persist();$('#plantDialog').close();planner();beds()};$('#save').onclick=()=>{persist();toast('Layout saved locally')};$('#clear').onclick=()=>{if(active&&confirm('Remove every plant from this bed?')){active.plants={};persist();planner();beds()}};$('#newIdea').onclick=()=>{const n=prompt('Idea bed name');if(n?.trim()){state.ideas.unshift(n.trim());persist();ideas()}};$('#ideaList').onclick=e=>{const b=e.target.closest('[data-commit]');if(b){const name=state.ideas[+b.dataset.commit];state.beds.push({id:'bed-'+Date.now(),year:state.year,name,shape:'rectangle',length:8,width:4,plants:{}});persist();beds();toast(`${name} added to ${state.year}`)}};$('#reset').onclick=()=>{if(confirm('Reset all planner data to the original demo?')){state=clone(demo);active=null;persist();render();show('beds')}};function render(){years();beds();ideas();palette();planner()}render();